//
// Stand-in for OpenTitan's abstract primitive `prim_flop_2sync` (normally generated by primgen).
// Selects the generic implementation prim_generic_flop_2sync (two prim_flop stages; the random
// CDC delay model inside it exists only under `SIMULATION`, which is not defined here).
module prim_flop_2sync #(
  parameter int               Width             = 16,
  parameter logic [Width-1:0] ResetValue        = '0,
  parameter bit               EnablePrimCdcRand = 1
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);

  prim_generic_flop_2sync #(
    .Width             (Width),
    .ResetValue        (ResetValue),
    .EnablePrimCdcRand (EnablePrimCdcRand)
  ) u_impl (
    .clk_i  (clk_i),
    .rst_ni (rst_ni),
    .d_i    (d_i),
    .q_o    (q_o)
  );

endmodule
